	async runCompoDocForSession(sessionId) {
		if (process.env.NODE_ENV === "test") {
			require_logger.logger.info(`[test mode] Skipping compodoc generation for session ${sessionId}`);
			return;
		}
		const session = this.sessions.get(sessionId);
		if (!session) {
			require_logger.logger.error(`Session ${sessionId} not found`);
			return;
		}
		try {
			require_logger.logger.info(`🚀 Generating documentation for session ${sessionId}`);
			const fakeProjectTsConfigPath = path.join(this.fakeProjectPath, "tsconfig.json");
			const findCli = (startDir) => {
				let dir = startDir;
				for (let i = 0; i < 8; i++) {
					const candidate = path.join(dir, "bin", "index-cli.js");
					if (fs_extra.existsSync(candidate)) return candidate;
					const parent = path.dirname(dir);
					if (parent === dir) break;
					dir = parent;
				}
			};
			const cliPath = process.env.COMPODOC_CLI_PATH ?? findCli(__dirname) ?? path.resolve(__dirname, "../bin", "index-cli.js");
			if (process.env.NODE_ENV === "test" && !fs_extra.existsSync(cliPath)) {
				require_logger.logger.warn(`CLI not found in test environment: ${cliPath}. Skipping documentation generation.`);
				session.documentationGenerated = true;
				return;
			}
			const cmd = [
				`node "${cliPath}"`,
				`-p "${fakeProjectTsConfigPath}"`,
				`-d "${session.documentationDir}"`,
				`--templates "${session.templateDir}"`
			];
			const config = session.config || {};
			const booleanFlags = [
				"hideGenerator",
				"disableSourceCode",
				"disableGraph",
				"disableCoverage",
				"disablePrivate",
				"disableProtected",
				"disableInternal",
				"disableLifeCycleHooks",
				"disableConstructors",
				"disableRoutesGraph",
				"disableSearch",
				"disableDependencies",
				"disableProperties",
				"disableDomTree",
				"disableTemplateTab",
				"disableStyleTab",
				"disableMainGraph",
				"disableFilePath",
				"disableOverview",
				"hideDarkModeToggle",
				"minimal",
				"serve",
				"open",
				"watch",
				"silent",
				"coverageTest",
				"coverageTestThresholdFail",
				"coverageTestShowOnlyFailed"
			];
			const valueFlags = [
				"theme",
				"language",
				"base",
				"customFavicon",
				"customLogo",
				"assetsFolder",
				"extTheme",
				"includes",
				"includesName",
				"output",
				"port",
				"hostname",
				"exportFormat",
				"coverageTestThreshold",
				"coverageMinimumPerFile",
				"unitTestCoverage",
				"gaID",
				"gaSite",
				"maxSearchResults",
				"toggleMenuItems",
				"navTabConfig"
			];
			for (const flag of booleanFlags) if (config[flag] === true) cmd.push(`--${flag}`);
			for (const flag of valueFlags) if (config[flag] !== void 0 && config[flag] !== "") {
				let value = config[flag];
				if (Array.isArray(value) || typeof value === "object") value = JSON.stringify(value);
				cmd.push(`--${flag} \"${value}\"`);
			}
			const fullCmd = cmd.join(" ");
			require_logger.logger.info(`🚀 Executing CompoDoc command: ${fullCmd}`);
			require("fs").appendFileSync("server-commands.log", `${(/* @__PURE__ */ new Date()).toISOString()} - ${fullCmd}\n`);
			(0, child_process.execSync)(fullCmd, {
				cwd: process.cwd(),
				stdio: "inherit"
			});
			this.updateSessionActivity(sessionId);
			require_logger.logger.info(`✅ Documentation generated successfully for session ${sessionId}`);
		} catch (error) {
			require_logger.logger.error(`❌ Error generating documentation for session ${sessionId}:`, error);
		}
	}
	startSessionCleanup() {
		this.cleanupInterval = setInterval(() => {
			const cutoffTime = Date.now() - 3600 * 1e3;
			for (const [sessionId, session] of this.sessions.entries()) if (session.lastActivity < cutoffTime) this.cleanupSession(sessionId);
		}, 600 * 1e3);
	}
	cleanupSession(sessionId) {
		const session = this.sessions.get(sessionId);
		if (session) try {
			if (fs_extra.existsSync(session.templateDir)) fs_extra.removeSync(session.templateDir);
			if (fs_extra.existsSync(session.documentationDir)) fs_extra.removeSync(session.documentationDir);
			const timer = this.debounceTimers.get(sessionId);
			if (timer) {
				clearTimeout(timer);
				this.debounceTimers.delete(sessionId);
			}
			for (const [ip, id] of this.ipToSessionId.entries()) if (id === sessionId) {
				this.ipToSessionId.delete(ip);
				break;
			}
			this.sessions.delete(sessionId);
			require_logger.logger.info(`🧹 Cleaned up session: ${sessionId}`);
		} catch (error) {
			require_logger.logger.error(`Error cleaning up session ${sessionId}:`, error);
		}
	}
