		const playgroundStaticPathSrc = path.join(process.cwd(), "src/resources/template-playground-app");
		const playgroundStaticPath = fs_extra.existsSync(playgroundStaticPathDist) ? playgroundStaticPathDist : playgroundStaticPathSrc;
		require_logger.logger.info(`📁 Setting up playground static files from: ${playgroundStaticPath}`);
		require_logger.logger.info(`📁 Playground static path exists: ${fs_extra.existsSync(playgroundStaticPath)}`);
